        ko: "\uC624\uB9AC\uC54C \uAE68 \uB123\uACE0 \uBD80\uCD94, \uC219\uC8FC, \uD53C\uAF2C\uB9C9 \uB123\uC5B4 \uB9C8\uBB34\uB9AC"
