        ja: "\u30B9\u30D1\u30A4\u30B9\u30DA\u30FC\u30B9\u30C8\u3068\u30BF\u30DE\u30EA\u30F3\u30C9\u3001\u30CF\u30FC\u30D6\u3092\u52A0\u3048\u3066\u716E\u8FBC\u3080",
        ko: "\uD5A5\uC2E0 \uD398\uC774\uC2A4\uD2B8, \uD0C0\uB9C8\uB9B0\uB4DC\uC640 \uD5C8\uBE0C \uB123\uC5B4 \uAE4A\uAC8C \uB053\uC774\uAE30"
