        ms: "Tolak Mee ke Tepi, Pecahkan Telur & Kacau Sebati",
        ja: "\u9EBA\u3092\u5BC4\u305B\u3066\u5375\u3092\u5272\u308A\u5165\u308C\u3001\u534A\u719F\u30B9\u30AF\u30E9\u30F3\u30D6\u30EB\u3092\u5168\u4F53\u306B\u7D61\u3081\u308B",
        ko: "\uBA74\uC744 \uBC00\uC5B4\uB450\uACE0 \uB2EC\uAC40\uC744 \uAE68 \uB123\uC5B4 \uC2A4\uD06C\uB7A8\uBE14\uD55C \uB4A4 \uD568\uAED8 \uC11E\uAE30"
