        en: "Charcoal Grill or Air Fry & Continually Splash Cascading Gravy",
        ms: "Bakar Atas Arang / Air Fryer & Siram Kuah Percik Berkali-kali",
        ja: "\u70AD\u706B\u307E\u305F\u306F\u30A8\u30A2\u30D5\u30E9\u30A4\u30E4\u30FC\u3067\u713C\u304D\u3001\u30BD\u30FC\u30B9\u3092\u4F55\u5EA6\u3082\u91CD\u306D\u5857\u308A\u3059\u308B",
        ko: "\uC22F\uBD88 \uB610\uB294 \uC5D0\uC5B4\uD504\uB77C\uC774\uC5B4\uC5D0 \uAD6C\uC6B0\uBA70 \uCF54\uCF54\uB11B \uC18C\uC2A4\uB97C \uBC18\uBCF5\uD574\uC11C \uBC14\uB974\uAE30"
