        ja: "\u30B9\u30D1\u30A4\u30B9\u30DA\u30FC\u30B9\u30C8\u3001\u30B3\u30B3\u30CA\u30C3\u30C4\u30DF\u30EB\u30AF\u3001\u5375\u3092\u52A0\u3048\u3066\u6DF7\u305C\u5408\u308F\u305B\u308B",
