        ja: "\u6C37\u5C71\u306E\u5468\u308A\u306B\u9BAE\u3084\u304B\u306A\u7FE1\u7FE0\u8272\u306E\u30C1\u30A7\u30F3\u30C9\u30EB\u30BC\u30EA\u30FC\u9EBA\u3092\u305F\u3063\u3077\u308A\u6563\u3089\u3057\u3001\u7518\u304F\u716E\u305F\u5C0F\u8C46\u3092\u6DFB\u3048\u307E\u3059\u3002\u7DD1\u3001\u8D64\u3001\u767D\u306E\u30B3\u30F3\u30C8\u30E9\u30B9\u30C8\u304C\u5357\u56FD\u306E\u6DBC\u3092\u6F14\u51FA\u3057\u307E\u3059\uFF01",
        ko: "\uC5BC\uC74C \uB3D4 \uC704\uC5D0 \uC0B0\uB73B\uD55C \uCD08\uB85D\uBE5B \uD310\uB2E8 \uCCB8\uB3CC \uC824\uB9AC \uB204\uB4E4\uACFC \uBD80\uB4DC\uB7FD\uAC8C \uC0B6\uC740 \uD1B5\uB2E8\uD325\uC744 \uB4EC\uBFCD \uB458\uB7EC \uC62C\uB9BD\uB2C8\uB2E4."
