        "zh-TW": "\u5E73\u5E95\u934B\u6162\u714E\u900F\u8584\u7DA0\u7389\u6591\u7D0B\u8584\u9905 (Dadar)",
        en: "Pan-Sear Thin, Mottled Jade Crepes without Flipping",
        ms: "Goreng Kulit Kuih Dadar Hijau Nipis Berlubang Halus",
        ja: "\u30D5\u30E9\u30A4\u30D1\u30F3\u3067\u6975\u8584\u306E\u7FE1\u7FE0\u8272\u30AF\u30EC\u30FC\u30D7\u751F\u5730\u3092\u713C\u304F\uFF08\u88CF\u8FD4\u3057\u4E0D\u8981\uFF09",
        ko: "\uD32C\uC5D0 \uC587\uC740 \uC5D0\uBA54\uB784\uB4DC\uBE5B \uD06C\uB808\uC774\uD504 \uBD80\uCCD0\uB0B4\uAE30 (\uB4A4\uC9D1\uC9C0 \uC54A\uC74C)"
